, [145]={npc="Jorn Vidente del Cielo", tgt="Jorn Vidente del Cielo", desc="Haz esto con los lagartos del trueno fuera del campamento. Ten preparadas tres botellas."}, [146]={hint="Llévale 3 unidades de sangre de truenagarto a Jorn Vidente del Cielo en el Campamento Taurajo.", desc="Haz esto con los lagartos del trueno fuera del campamento. Ten preparadas tres botellas."}, [147]={npc="Jorn Vidente del Cielo", tgt="Jorn Vidente del Cielo", desc="Haz esto con los lagartos del trueno fuera del campamento. Ten preparadas tres botellas."}, [148]={npc="Jorn Vidente del Cielo", tgt="Jorn Vidente del Cielo"}, [149]={hint="Encuentra 1 halcón trueno, mátalo y llévale sus alas a Jorn Vidente del Cielo en el Campamento Taurajo."}, [150]={npc="Jorn Vidente del Cielo", tgt="Jorn Vidente del Cielo"}, [151]={text="Vuele de regreso al El Cruce para entregar las misiones restantes, luego diríjase hacia el oeste pasando El Alto del Honor (35.26, 27.88) hasta Stonetalon."}, [152]={npc="Mankrik", tgt="Mankrik"}, [153]={npc="Mankrik", tgt="Mankrik"}, [154]={npc="Korran", tgt="Korran"}, [155]={hint="Llévale la calavera de Lok a Thork en El Cruce, en Los Baldíos.", tag="Opcional"}, [156]={npc="Thork", tgt="Thork", tag="Opcional"}, [157]={npc="Sorek", tgt="Sorek", tag="Opcional", desc="Otras pastillas: Torm Tótem de Ira en Cima del Trueno o Baltus Fowler en Entrañas."}, [158]={hint="Habla con Ruga Tótem de Ira.", tag="Opcional", desc="Acepte de un entrenador en Orgrimmar, Cima del Trueno o Entrañas."}, [159]={npc="Ruga Tótem de Ira", tgt="Ruga Tótem de Ira", tag="Opcional", desc="Acepte de un entrenador en Orgrimmar, Cima del Trueno o Entrañas."}, [160]={npc="Ruga Tótem de Ira", tgt="Ruga Tótem de Ira", tag="Opcional", desc="Haga esto junto con las misiones Campamento Taurajo."}, [161]={hint="Lleva 5 antenas agitadas a Ruga Tótem de Ira de Campamento Taurajo.", tag="Opcional", desc="Haga esto junto con las misiones Campamento Taurajo."}, [162]={npc="Ruga Tótem de Ira", tgt="Ruga Tótem de Ira