    [2283] = {n="La recuperación del collar", d="Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar. Puede que el collar esté estropeado.", tgo={{"Perito de Forjatiniebla", "Rufián de Forjatiniebla", "Cavador de Forjatiniebla"}}},
    [2284] = {n="La recuperación del collar, 2ª parte", d="Busca pistas sobre el paradero de las gemas en las profundidades de Uldaman."},
    [2318] = {n="La traducción del diario", d="Encuentra a alguien que pueda traducir el diario del paladín. El lugar más cercano en el que podrás encontrar a alguien es Kargath, en las Tierras Inhóspitas."},
    [2338] = {n="La traducción del diario", d="Préstale el collar a Jarkal. A cambio, te traducirá el diario."},
    [2339] = {n="Encuentra las gemas y la fuente de alimentación", d="Recupera las 3 gemas y una fuente de energía para el collar de Uldaman y llévalo todo a Jarkal Musgofusión en Kargath. Jarkal cree que es posible que la fuente de energía más poderosa se halle en un ensamblaje de Uldaman.\nPor el diario sabes...\n* Que han ocultado el rubí en una zona cerrada con barricadas en Forjatiniebla.\n* Que el topacio se ha ocultado en una urna en un área trogg, cerca de los enanos de la Alianza.\n* Que Grimlok, el jefe trogg, se ha quedado con el zafiro.", tgo={{}, {"Grimlok"}, {}, {"Archaedas"}}, objs={"Alijo de Forjatiniebla", "Urna llamativa"}},
    [2340] = {n="Entregar las gemas", d="Entrégale el collar y la gema recuperados a Dran Droffers en Orgrimmar."},
    [2341] = {n="La recuperación del collar, 3ª parte", d="Habla con Jarkal Musgofusión en Kargath."},
    [2342] = {n="Los tesoros reclamados", d="Coge el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas.", objs={"Cofre de la familia Garrett"}},
    [2378] = {n="Encuentra a los Mano Destrozada", d="Viaja a Orgrimmar y habla con Shenthul, que estará en el Circo de las Sombras.|n"},
    [2379] = {n="Zando'zan", d="Habla con Zando'zan en el Circo de las Sombras."},
    [2381] = {n="Saquear a los saqueadores", d="Llévale el tesoro de los Mares del Sur a Desdio el Desdichado en Trinquete. No olvides conseguir una G.E.A.Q. y herramientas de ladrones del aparato Gizmotrónico de Wrenix. Necesitarás todo eso para completar tu misión.\nSi te atacaran unos loros anormalmente agresivos, ¡usa la G.E.A.Q.!|n|n", tgo={{"Polly"}}},
    [2382] = {n="Desdio de Trinquete", d="Viaja a Trinquete y habla con Desdio el Desdichado."},
    [2383] = {n="Papiro simple", d="Lee el Pergamino simple y habla con Frang en el Valle de los Retos."},
    [2418] = {n="Las piedras de energía", d="Llévale 8 piedras de energía de dentrio y 8 piedras de energía de An'Alleum a Aparejez en las Tierras Inhóspitas.", tgo={{"Perito de Forjatiniebla", "Rufián de Forjatiniebla", "Cavador de Forjatiniebla"}, {"Perito de Forjatiniebla", "Rufián de Forjatiniebla", "Cavador de Forjatiniebla"}}},
    [2458] = {n="Agente encubierto", d="Ve a la torre de Ventura y Cía., al norte de El Fangal, y localiza al capataz Fizzule, el agente de Mano Destrozada.\nCuando veas la torre, usa la pistola de bengalas para avisar de tu llegada al capataz Fizzule. Lanza 2 bengalas y acércate al capataz para darle el /saludo de los Mano Destrozada.\nTienes que hacerlo en este orden, porque Fizzule te matará si no te reconoce."},
    [2460] = {n="El saludo de los Mano Destrozada", d="Da el saludo de los Mano Destrozada a Shenthul.", tgo={{"Shenthul"}}},
    [2478] = {n="Misión: Posible, pero no probable", d="Roba la llave de la torre del supervisor Silixiz, mata a 2 zánganos mutados de Ventura y Cía., 2 patrullas de Ventura y Cía. y 2 oteadores de Ventura y Cía.\nAsesina al gran supervisor Puzik Gallywix y quédate con su cabeza, fuerza la cerradura del arcón de Gallywix y roba la mezcla de Zanzil modificada que allí está oculta. Lleva el alijo y la cabeza de Gallywix a Shenthul en Orgrimmar, él te dará más instrucciones.|n", tgo={{"Zángano mutado de Ventura y Cía."}, {"Vigía de Ventura y Cía."}, {"Patrulla de Ventura y Cía."}, {"Gran Supervisor Puzik Gallywix"}, {"Supervisor Silixiz"}, {}}, objs={"Arcón de Gallywix"}},
    [2479] = {n="La ayuda de Hinott", d="Ve a Molino Tarren, en Laderas de Trabalomas, para entregar la muestra de Zanzil a Serge Hinott.\nPara llegar a Molino Tarren, coge el zepelín a Entrañas y sigue el camino hacia el sur por el Bosque de Argénteos hacia Trabalomas. ¡Sigue las indicaciones!|n|n"},
    [2480] = {n="La ayuda de Hinott", d="Espera a que Serge Hinott te cure."},
    [2521] = {n="Al servicio de Kum'isha", d="En tus viajes por Las Tierras Devastadas, si te encontraras con una esfera draenetista perfecta, llévasela a Kum'isha el Coleccionista.\nTen cuidado, esta gema es uno de los cristales más raros de todo Azeroth. Cualquier criatura de estas tierras podría tener una.\nSe te recompensará por cada esfera draenetista perfecta que consigas.", tgo={{"Ogro Fauzatroz", "Mago ogro Fauzatroz", "Tosco Fauzatroz"}}},
    [2581] = {n="Papadas de hiena risitas", d="Llévale 3 papadas de hiena risitas, 2 pulmones de jabalí maldito y 1 pinza de scorpok al mago sangriento Drazial.", tgo={{"Hiena risitas famélica", "Hiena risitas", "Devastatia"}, {"Jabalí Cenicrín", "Jabinferno", "Gruñón"}, {"Aguijonero Scorpok", "Clack el Atracador"}}},
