    [97289] = {n="Tormento eterno", d="Lleva la cabeza del Barón al cuerpo de Othmar en Entrañas."},
    [97290] = {n="Tormento eterno", d="Informa tus hallazgos al maestro boticario Faranell en Entrañas."},
    [97291] = {n="Tormento eterno", d="Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a las instructoras de herboristería para reunir hierba ampolla y a los vendedores de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas.", objs={"Hierba ampolla"}},
    [97292] = {n="Tormento eterno", d="Inyecta el suero siseante en el sistema que está encima del cuerpo de Othmar para el maestro boticario Faranell.", objs={"Othmar's Head"}},
    [97327] = {n="Blackmaw Pouches", d="Botín de: Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", tgo={{"Blackmaw Berserker", "Blackmaw Thrall", "Blackmaw Headhunter"}}},
    [97328] = {n="Todo lo que tenga valor", d="Recupera 8 cargamentos robados de las Ruinas de Zul'Kunda en Vega de Tuercespina y entrégale tu botín a alguien en Bahía del Botín."},
    [97329] = {n="Where's the Key?", d="Botín de: Explorador Sangrapellejo, Cazador Sangrapellejo, Rabioso Sangrapellejo", tgo={{"Explorador Sangrapellejo", "Cazador Sangrapellejo", "Rabioso Sangrapellejo"}}},
    [97331] = {n="Zimmix's Great Escape", d="Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue."},
    [97332] = {n="Twice Misplaced Trust", d="Deliver the Twice Reordered Package to Wharfmaster Whizzbuzz at Powderfuse Port in the Riverglades."},
    [97386] = {n="El ataque de Grom'gol", d="<name> comandante Aggro'gosh del Campamento Grom'gol quiere que mates a los ogros en el Túmulo Ogro Mosh'Ogg.", tgo={{"Creaconjuros Mosh'Ogg"}, {"Belicista Mosh'Ogg"}, {"Aplastador Mosh'Ogg"}, {"Chamán Mosh'Ogg"}}},
    [97453] = {n="Malezas erradicadas", d="Mata 6 malezas carnívoras al sur de Grom'gol y luego informa a la madre de Gemmil.", tgo={{"Hierba carnívora"}}},
    [97485] = {n="Tradiciones de la Cima", d="Cómprale un fardo de hierbas a Nida, la herborista; un fardo de ramitas de cedro a Nata, la proveedora de encantamiento; un hilo de tendón a Mahu, el proveedor de peletería; y sílex y yesca ceremoniales a Naal, el proveedor de cocina.\nCombina estos objetos y esparce el incienso por el Alto de los Cazadores.", objs={"Quemador de incienso"}},
    [97530] = {n="Dunemaul Dues", d="Botín de: Ogro Machacaduna, Déspota Machacaduna, Magro ogro Machacaduna", tgo={{"Ogro Machacaduna", "Déspota Machacaduna", "Magro ogro Machacaduna"}}},
    [97534] = {n="Gritty Business", d="Quinn wants you to recover 7 pieces of Desert Debris and return to her in Gadgetzan."},
    [97539] = {n="Suturas de seda", d="Llévale 12 pedazos de seda de araña quirúrgica al Doctor Gregory Victor en Sentencia, en las Tierras Altas de Arathi.", tgo={{"Trepador de las llanuras", "Trepador de las llanuras gigante"}}},
    [97558] = {n="Pellejos para los Renegados", d="Lleva 8 membranas de alas de murciumbrío, 6 pellejos de can oscuro y 3 pieles de múrloc Anca Vil a Shelene Rhobart.", tgo={{"Murciumbrío superior", "Murciumbrío vampírico"}, {"Can oscuro decrépito", "Can oscuro maldito"}, {"Oráculo menor Anca Vil", "Habitabosta Anca Vil"}}},
    [97908] = {n="Campamento básico: Desuello", d="Habla con Thuwd en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", tgo={{"Thuwd"}}},
    [97936] = {n="Campamento básico: Desuello", d="Habla con Yonn Corte Profundo en Poblado Pezuña de Sangre para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", tgo={{"Yonn Corte Profundo"}}},
