    [98070] = {n="Acalla los chillidos", d="Mata 5 arpías estridentes, 5 arpías malapluma estridentes y 5 arpías clamavientos estridentes.", tgo={{"Arpía estridente"}, {"Malapluma estridente"}, {"Clamavientos estridente"}}},
    [98093] = {n="Campo despejado", d="Sulhasa, en los Baldíos del Sur, quiere que elimines 7 lagartos tormenteros y 7 acechadores dentecenados de la zona para que pueda bajar del árbol de manera segura.", tgo={{"Acechador Dentecenado"}, {"Tormentero"}}},
