    [98430] = {n="Los Zancalargos", d="Ayuda a Perith Pezuña Tempestuosa a escapar de Roca Crines Pálidas hacia un lugar seguro, e informa a Cairne Pezuña de Sangre en Cima del Trueno."},
    [98435] = {n="Informe de Tronacuerno", d="Lleva el informe de Tronacuerno al archidruida Hamuul Tótem de Runa en Cima del Trueno."},
