    [98601] = {n="Un camino difícil", d="Lee el pergamino consagrado, luego ve a la iglesia de Camposanto y habla con Aramis Manomartillo."},
    [98738] = {n="Bendiciones del gran espíritu felino natoviento", d="Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna."},
    [98739] = {n="Bendiciones del gran espíritu felino.", d="Habla con Dendrita."},
